131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
134	        Owner owner = this.clinicService.findOwnerById(ownerId);
135	        if (owner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
144	        normalizeAddress(ownerFieldsDto);
145	        rejectBlankOwnerFields(ownerFieldsDto);
146	        rejectInvalidPostcode(ownerFieldsDto);
147	        normalizeTelephone(ownerFieldsDto);
148	        normalizeEmail(ownerFieldsDto);
149	        String householdId = HouseholdNormalizer.toHouseholdId(
150	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
151	        rejectDuplicateIdentity(ownerFieldsDto, householdId);
152	        rejectCityAtCapacity(ownerFieldsDto.getCity());
153	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
154	        long registeredThatDay = countRegisteredOn(registrationDate);
155	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
156	        HttpHeaders headers = new HttpHeaders();
157	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
158	        owner.setRegistrationDate(registrationDate);
159	        owner.setHouseholdId(householdId);
160	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
161	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
162	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
163	        this.clinicService.saveOwner(owner);
164	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
165	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
166	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
167	        headers.setLocation(UriComponentsBuilder.newInstance()
168	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
169	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
175	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
176	        if (currentOwner == null) {
177	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	        }
179	        currentOwner.setAddress(ownerFieldsDto.getAddress());
180	        currentOwner.setCity(ownerFieldsDto.getCity());
181	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
182	        currentOwner.setLastName(ownerFieldsDto.getLastName());
183	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
184	        normalizeEmail(ownerFieldsDto);
185	        currentOwner.setEmail(ownerFieldsDto.getEmail());
186	        currentOwner.setHouseholdId(
187	            HouseholdNormalizer.toHouseholdId(currentOwner.getLastName(), currentOwner.getAddress()));
188	        this.clinicService.saveOwner(currentOwner);
189	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Transactional
194	    @Override
195	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
196	        Owner owner = this.clinicService.findOwnerById(ownerId);
197	        if (owner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        this.clinicService.deleteOwner(owner);
201	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
207	        Owner owner = this.clinicService.findOwnerById(ownerId);
208	        if (owner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        HttpHeaders headers = new HttpHeaders();
212	        Pet pet = petMapper.toPet(petFieldsDto);
213	        owner.setId(ownerId);
214	        pet.setOwner(owner);
215	        pet.getType().setName(null);
216	        this.clinicService.savePet(pet);
217	        PetDto petDto = petMapper.toPetDto(pet);
218	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
219	            .buildAndExpand(pet.getId()).toUri());
220	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
221	    }
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
226	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
227	        if (currentOwner != null) {
228	            Pet currentPet = this.clinicService.findPetById(petId);
229	            if (currentPet != null) {
230	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
231	                currentPet.setName(petFieldsDto.getName());
232	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
233	                this.clinicService.savePet(currentPet);
234	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
235	            }
236	        }
237	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
